INSERT INTO cms.portfolio_item (id, category_id, slug, title_en, title_ar, client_name, year, subtitle_en, subtitle_ar, price, price_note_en, price_note_ar, external_url, location) VALUES ('port-1', 'pcat-cms-1', 'meridian-advisory-case-1', 'Family Conglomerate Holding Restructuring', 'إعادة هيكلة مجموعة عائلية قابضة بالبحرين', 'Al-Jazeera Gulf Holdings W.L.L.', 2025, 'Delivered for Al-Jazeera Gulf Holdings W.L.L. across Diplomatic Area with measurable SLA benchmarks.', 'تم التنفيذ لصالح مجموعة الجزيرة الخليجية القابضة في Diplomatic Area وفق أعلى معايير الجودة والالتزام.', 5600, 'Turnkey scope including 10% NBR VAT compliance (BHD)', 'باقة تنفيذ متكاملة شاملة التقارير وضريبة القيمة المضافة', 'https://meridianbh.com/work/meridian-advisory-case-1', 'Diplomatic Area, Bahrain') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-1', 'meridian-advisory-2026-outlook', 'Meridian Advisory 2026 GCC Market Outlook & Benchmarks', 'توقعات أسواق الخليج ومعايير الأداء لعام 2026 — ميريديان للاستشارات', 'Key operational benchmarks, real metrics, and 2026 guidance from Meridian Advisory in Diplomatic Area.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من ميريديان للاستشارات في Diplomatic Area.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Management and financial consultancy advising family conglomerates and growth-stage companies on restructuring, VAT compliance, and expansion. Focusing on Internal Controls & Risk Review, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"شركة استشارات إدارية ومالية تدعم المجموعات العائلية والشركات النامية في إعادة الهيكلة والامتثال الضريبي والتوسع. من خلال خدمة مراجعة الضوابط الداخلية والمخاطر نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Management and financial consultancy advising family conglomerates and growth-stage companies on restructuring, VAT compliance, and expansion.</p><p>Focusing on <strong>Internal Controls & Risk Review</strong>, our Diplomatic Area specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>شركة استشارات إدارية ومالية تدعم المجموعات العائلية والشركات النامية في إعادة الهيكلة والامتثال الضريبي والتوسع.</p><p>من خلال خدمة <strong>مراجعة الضوابط الداخلية والمخاطر</strong>، يعمل فريقنا في Diplomatic Area على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-01.png', 'Meridian Advisory 2026 GCC Market Outlook & Benchmarks | Meridian Advisory', 'توقعات أسواق الخليج ومعايير الأداء لعام 2026 — ميريديان للاستشارات | ميريديان للاستشارات', 'Executive guide by Meridian Advisory covering Internal Controls & Risk Review benchmarks in Bahrain.', 'دليل تنفيذي من ميريديان للاستشارات حول معايير مراجعة الضوابط الداخلية والمخاطر في البحرين.', 'Insights', '{"services","insights","Diplomatic Area","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '6 days', true, now() - interval '6 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-1', 'How quickly can Meridian Advisory initiate a Internal Controls & Risk Review engagement?', 'كم يستغرق بدء تنفيذ خدمة مراجعة الضوابط الداخلية والمخاطر لدى ميريديان للاستشارات؟', 'Discovery and kickoff begin within 48 hours of quotation sign-off, with a dedicated lead assigned in Diplomatic Area.', 'يبدأ التخطيط والتنفيذ خلال 48 ساعة من اعتماد عرض السعر مع تعيين مدير حساب مخصص في Diplomatic Area.', 'services', true, 1, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.portfolio_item (id, category_id, slug, title_en, title_ar, client_name, year, subtitle_en, subtitle_ar, price, price_note_en, price_note_ar, external_url, location) VALUES ('port-2', 'pcat-cms-2', 'meridian-advisory-case-2', 'Manufacturing Cost-Down Transformation', 'مشروع خفض التكاليف التشغيلية الصناعية', 'Bahrain Bay Hospitality Group', 2026, 'Delivered for Bahrain Bay Hospitality Group across Diplomatic Area with measurable SLA benchmarks.', 'تم التنفيذ لصالح مجموعة خليج البحرين للضيافة في Diplomatic Area وفق أعلى معايير الجودة والالتزام.', 1260, 'Turnkey scope including 10% NBR VAT compliance (BHD)', 'باقة تنفيذ متكاملة شاملة التقارير وضريبة القيمة المضافة', 'https://meridianbh.com/work/meridian-advisory-case-2', 'Diplomatic Area, Bahrain') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-2', 'meridian-advisory-service-standards', 'Inside Our Advisory SLA: Speed, Quality & Auditability', 'معايير اتفاقية مستوى الخدمة والجودة في مراجعة الضوابط الداخلية والمخاطر', 'Key operational benchmarks, real metrics, and 2026 guidance from Meridian Advisory in Diplomatic Area.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من ميريديان للاستشارات في Diplomatic Area.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Management and financial consultancy advising family conglomerates and growth-stage companies on restructuring, VAT compliance, and expansion. Focusing on VAT Compliance & Filing Retainer, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"شركة استشارات إدارية ومالية تدعم المجموعات العائلية والشركات النامية في إعادة الهيكلة والامتثال الضريبي والتوسع. من خلال خدمة الامتثال والإقرارات الضريبية الشهرية نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Management and financial consultancy advising family conglomerates and growth-stage companies on restructuring, VAT compliance, and expansion.</p><p>Focusing on <strong>VAT Compliance & Filing Retainer</strong>, our Diplomatic Area specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>شركة استشارات إدارية ومالية تدعم المجموعات العائلية والشركات النامية في إعادة الهيكلة والامتثال الضريبي والتوسع.</p><p>من خلال خدمة <strong>الامتثال والإقرارات الضريبية الشهرية</strong>، يعمل فريقنا في Diplomatic Area على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-02.png', 'Inside Our Advisory SLA: Speed, Quality & Auditability | Meridian Advisory', 'معايير اتفاقية مستوى الخدمة والجودة في مراجعة الضوابط الداخلية والمخاطر | ميريديان للاستشارات', 'Executive guide by Meridian Advisory covering VAT Compliance & Filing Retainer benchmarks in Bahrain.', 'دليل تنفيذي من ميريديان للاستشارات حول معايير الامتثال والإقرارات الضريبية الشهرية في البحرين.', 'Operations', '{"services","operations","Diplomatic Area","2026"}'::text[], 'Bader Ali', 'published', now() - interval '12 days', true, now() - interval '12 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-2', 'Do all invoices include Bahrain NBR 10% VAT and Arabic breakdown?', 'هل تشمل الفواتير ضريبة القيمة المضافة 10% والتفصيل باللغتين؟', 'Yes. Every tax invoice is issued in BHD under CR CR-141022-3 and VAT ID 200014102200002 with itemized bilingual lines.', 'نعم، تصدر جميع الفواتير الضريبية بعملة BHD وفق السجل CR-141022-3 والرقم الضريبي 200014102200002.', 'billing', true, 2, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
