INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-4', 'meridian-advisory-vat-e-invoicing-readiness', 'Navigating NBR 10% VAT Compliance & Clean Audit Trails', 'الامتثال لضريبة القيمة المضافة 10% وتدقيق الفواتير', 'Key operational benchmarks, real metrics, and 2026 guidance from Meridian Advisory in Diplomatic Area.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من ميريديان للاستشارات في Diplomatic Area.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Management and financial consultancy advising family conglomerates and growth-stage companies on restructuring, VAT compliance, and expansion. Focusing on Board Strategy & Growth Architecture, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"شركة استشارات إدارية ومالية تدعم المجموعات العائلية والشركات النامية في إعادة الهيكلة والامتثال الضريبي والتوسع. من خلال خدمة استراتيجيات النمو وتطوير مجالس الإدارة نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Management and financial consultancy advising family conglomerates and growth-stage companies on restructuring, VAT compliance, and expansion.</p><p>Focusing on <strong>Board Strategy & Growth Architecture</strong>, our Diplomatic Area specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>شركة استشارات إدارية ومالية تدعم المجموعات العائلية والشركات النامية في إعادة الهيكلة والامتثال الضريبي والتوسع.</p><p>من خلال خدمة <strong>استراتيجيات النمو وتطوير مجالس الإدارة</strong>، يعمل فريقنا في Diplomatic Area على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-01.png', 'Navigating NBR 10% VAT Compliance & Clean Audit Trails | Meridian Advisory', 'الامتثال لضريبة القيمة المضافة 10% وتدقيق الفواتير | ميريديان للاستشارات', 'Executive guide by Meridian Advisory covering Board Strategy & Growth Architecture benchmarks in Bahrain.', 'دليل تنفيذي من ميريديان للاستشارات حول معايير استراتيجيات النمو وتطوير مجالس الإدارة في البحرين.', 'Finance', '{"services","finance","Diplomatic Area","2026"}'::text[], 'Bader Ali', 'published', now() - interval '24 days', false, now() - interval '24 days', now()) ON CONFLICT (id) DO NOTHING;
