INSERT INTO cms.website_content (id, draft, published, previous, revision, published_at, updated_at) VALUES ('main', '{"company":{"nameEn":"Meridian Business Advisory S.P.C.","nameAr":"ميريديان لاستشارات الأعمال ذ.م.م","shortEn":"Meridian Advisory","shortAr":"ميريديان للاستشارات","taglineEn":"Financial Advisory, Governance & Strategy Consulting","taglineAr":"الاستشارات المالية والحوكمة وتطوير الاستراتيجيات","aboutEn":"Management and financial consultancy advising family conglomerates and growth-stage companies on restructuring, VAT compliance, and expansion.","aboutAr":"شركة استشارات إدارية ومالية تدعم المجموعات العائلية والشركات النامية في إعادة الهيكلة والامتثال الضريبي والتوسع."},"hero":{"titleEn":"Meridian Advisory — Financial Advisory, Governance & Strategy Consulting","titleAr":"ميريديان للاستشارات — الاستشارات المالية والحوكمة وتطوير الاستراتيجيات","ctaLabelEn":"Explore Meridian Advisory","ctaLabelAr":"استكشف ميريديان للاستشارات"},"featuredServices":[{"code":"SVC-AUD","en":"Internal Controls & Risk Review","ar":"مراجعة الضوابط الداخلية والمخاطر","rate":2800},{"code":"SVC-VAT","en":"VAT Compliance & Filing Retainer","ar":"الامتثال والإقرارات الضريبية الشهرية","rate":420},{"code":"SVC-STR","en":"5-Year Financial Modeling","ar":"بناء النماذج المالية الخمسية","rate":1950},{"code":"ADV-STR","en":"Board Strategy & Growth Architecture","ar":"استراتيجيات النمو وتطوير مجالس الإدارة","rate":3100}]}'::jsonb, '{"company":{"nameEn":"Meridian Business Advisory S.P.C.","nameAr":"ميريديان لاستشارات الأعمال ذ.م.م","shortEn":"Meridian Advisory","shortAr":"ميريديان للاستشارات","taglineEn":"Financial Advisory, Governance & Strategy Consulting","taglineAr":"الاستشارات المالية والحوكمة وتطوير الاستراتيجيات","aboutEn":"Management and financial consultancy advising family conglomerates and growth-stage companies on restructuring, VAT compliance, and expansion.","aboutAr":"شركة استشارات إدارية ومالية تدعم المجموعات العائلية والشركات النامية في إعادة الهيكلة والامتثال الضريبي والتوسع.